// icon returns the inline SVG for a lucide icon name (kebab-case), styled like
// the upstream default: 24x24 viewBox, stroke currentColor. Unknown names
// render nothing.
func icon(name string) template.HTML {
	inner, ok := iconSVGs[name]
	if !ok {
		return ""
	}
	return template.HTML(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="lucide">` + inner + `</svg>`)
}
